mapper.select:
select sum(account_now) from member_info
and register_time >= STR_TO_DATE(CONCAT(#{req.inclusive_date},' 00:00:00'),'%Y-%m-%d %H:%i:%s') and register_time <= STR_TO_DATE(CONCAT(#{req.inclusive_date},' 23:59:59'),'%Y-%m-%d %H:%i:%s')
and inviter_code = #{req.channelCode}

select count(id) total_registration from member_info
and register_time >= STR_TO_DATE(CONCAT(#{req.inclusive_date},' 00:00:00'),'%Y-%m-%d %H:%i:%s') and register_time <= STR_TO_DATE(CONCAT(#{req.inclusive_date},' 23:59:59'),'%Y-%m-%d %H:%i:%s')
and inviter_code = #{req.channelCode}
